import{_ as e,o as s,c as o,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const t="/images/admin/dashboard-kpis.png",h=JSON.parse('{"title":"2. Cómo Leer los Números de tu Negocio (Dashboard)","description":"","frontmatter":{},"headers":[],"relativePath":"admin/dashboard.md","filePath":"admin/dashboard.md"}'),n={name:"admin/dashboard.md"};function i(d,a,l,c,p,m){return s(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_2-como-leer-los-numeros-de-tu-negocio-dashboard" tabindex="-1">2. Cómo Leer los Números de tu Negocio (Dashboard) <a class="header-anchor" href="#_2-como-leer-los-numeros-de-tu-negocio-dashboard" aria-label="Permalink to &quot;2. Cómo Leer los Números de tu Negocio (Dashboard)&quot;">​</a></h1><p>El <strong>Dashboard</strong> (<a href="https://pyme.rsfsecure.site/admin/dashboard" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/dashboard</a>) es la primera pantalla que verás al entrar. Te muestra en tiempo real cómo van las ventas del día, qué pedidos están pendientes de atención y si algún producto se está agotando.</p><hr><h2 id="_2-1-tarjetas-de-resumen-kpis-en-vivo" tabindex="-1">2.1 Tarjetas de Resumen (KPIs en Vivo) <a class="header-anchor" href="#_2-1-tarjetas-de-resumen-kpis-en-vivo" aria-label="Permalink to &quot;2.1 Tarjetas de Resumen (KPIs en Vivo)&quot;">​</a></h2><p>En la parte superior de la pantalla verás 4 tarjetas con los datos más importantes:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Pantalla Principal con Métricas de Venta</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/dashboard</span></div><div class="screenshot-body"><img src="'+t+'" alt="Pantalla Principal con Métricas de Venta"></div></div><h3 id="¿que-significa-cada-tarjeta" tabindex="-1">¿Qué significa cada tarjeta? <a class="header-anchor" href="#¿que-significa-cada-tarjeta" aria-label="Permalink to &quot;¿Qué significa cada tarjeta?&quot;">​</a></h3><ul><li><strong>Ingresos Totales (en USD/PAB):</strong> Todo el dinero cobrado por ventas en el período actual.</li><li><strong>Total de Pedidos:</strong> Cuántas compras han realizado los clientes.</li><li><strong>Tasa de Conversión:</strong> De cada 100 personas que entran a la tienda, cuántas completan una compra.</li><li><strong>Alertas de Stock Bajo:</strong> Te avisa cuántos productos tienen pocas unidades en bodega para que no te quedes sin mercancía.</li></ul><hr><h2 id="_2-2-graficos-de-ventas-y-metodos-de-pago" tabindex="-1">2.2 Gráficos de Ventas y Métodos de Pago <a class="header-anchor" href="#_2-2-graficos-de-ventas-y-metodos-de-pago" aria-label="Permalink to &quot;2.2 Gráficos de Ventas y Métodos de Pago&quot;">​</a></h2><ul><li><strong>Gráfica de Ventas:</strong> Te permite ver si las ventas de esta semana o mes están subiendo en comparación con el mes anterior.</li><li><strong>Porcentaje por Forma de Pago:</strong> Te muestra si tus clientes prefieren pagar con <strong>Yappy</strong>, <strong>Tarjeta</strong> o <strong>Transferencia ACH</strong>, lo cual te ayuda a planificar promociones.</li></ul><hr><h2 id="_2-3-tabla-de-ultimos-pedidos-recibidos" tabindex="-1">2.3 Tabla de Últimos Pedidos Recibidos <a class="header-anchor" href="#_2-3-tabla-de-ultimos-pedidos-recibidos" aria-label="Permalink to &quot;2.3 Tabla de Últimos Pedidos Recibidos&quot;">​</a></h2><p>En la parte baja de la pantalla tienes la lista de las últimas compras recibidas:</p><ol><li>Puedes ver el nombre del cliente, la hora de compra y el monto pagado.</li><li>Verás la etiqueta de estado de color:</li></ol><ul><li>Pendiente: <strong>Amarillo:</strong> Pendiente de revisión de pago.</li><li>Activo: <strong>Verde:</strong> Pagado, listo para empacar.</li></ul><ol start="3"><li>Haz clic en el icono del <strong>ojo ``</strong> al final de la fila para abrir el pedido y gestionarlo.</li></ol>',17)])])}const g=e(n,[["render",i]]);export{h as __pageData,g as default};
